# -*- coding: utf-8 -*-
# 中文信经文本采自华人改革宗《赞美手册》（Book of Praise）中文版：
# https://ccifellowship.org/books/book-of-praise/creeds
# 《亚他那修信经》该版为 42 点编号（传统《公祷书》英文本常作 44 句）。

APOSTLES_ZH = ['我信神，全能的父，创造天地的主。', '我信我主耶稣基督，神的独生子；', '因圣灵感孕，从童贞女马利亚所生；', '在本丢·彼拉多手下受难，被钉在十字架上，受死，被埋葬，降在阴间；', '第三天从死里复活；', '他升天，坐在全能父神的右边；', '将来必从那里降临，审判活人死人。', '我信圣灵。', '我相信圣而公之教会，我相信圣徒相通；', '我相信罪得赦免；', '我相信身体复活；', '我相信永生。阿们！']

NICENE_ZH = ['我们信独一的神，全能的父，创造天地及其中可见不可见之万物的主。', '我们信独一主耶稣基督，神的独生子，在万世以前为父所生；', '出于神且是神，出于光且是光，出于真神且是真神；受生却非被造，与父同质；万物都是藉着他造的。', '为了拯救我们，他从天上降世为人，即藉着从圣灵感孕的童女马利亚道成肉身。', '他为了我们，在本丢·彼拉多手下被钉十字架；受难、被埋葬；', '照着圣经所说，他在第三天复活，并升天、坐在父的右边；', '将来必在荣耀中再来，审判活人死人；他的国没有穷尽。', '我们信圣灵，赐生命的主，他从父和子而出，', '与父和子同受敬拜和尊崇；他曾藉众先知说话。', '我们相信世上只有一个圣而公之使徒性教会；', '我们承认印证了罪得赦免的独一洗礼；', '我们盼望从死里复活，以及完全被更新的世界的到来。阿们！']

ATH_ZH = ['所有渴慕得救的人都必须持守大公信仰胜过其他一切。', '人若不信此信仰中的任何一条，都必永远沉沦。', '大公信仰是，我们敬拜一体三位又三位一体的神，', '其位格不紊，其本质不分，', '因为父是一位，子是一位，圣灵又是一位；', '但父、子、圣灵同是一位神，三个位格同荣耀，其威严也同永恒。', '父如何，子就如何，圣灵也如何。', '父非受造，子非受造，圣灵也非受造。', '父无限，子无限，圣灵也无限。', '父永恒，子永恒，圣灵也永恒。', '父、子、圣灵非三位永恒者，乃一位永恒者；', '非三位非受造者，乃一位非受造者；非三位无限者，乃一位无限者。', '同样，父全能，子全能，圣灵也全能；', '父、子、圣灵非三位全能者，乃一位全能者。', '因此，父是神，子是神，圣灵也是神；', '但父、子、圣灵非三位神，乃一位神。', '因此，父是主，子是主，圣灵也是主；', '但父、子、圣灵非三位主，乃一位主。', '正如按照基督教真理我们必须承认每一位都既是神又是主一样，', '按照大公信仰，我们不可说他们是三位神、三位主。', '父是自有的，既非受造，也非受生。', '子独出于父，非受造，乃是受生。', '圣灵从父和子而出，非受造，也非受生。', '因此，只有一位父，非三位父；只有一位子，非三位子；只有一位圣灵，非三位圣灵。', '父、子、圣灵无先后、无尊卑，', '同永恒，是平等的三个位格。', '因此如前所述，在凡事上，一体三位又三位一体的神须同受敬拜。', '渴慕得救的人必须如此思想三位一体的神。', '同时，要得永远的救赎，就须信道成肉身的主耶稣基督。', '纯正的信仰就是我们相信并宣告我们的主耶稣基督，神的独生子，既是神又是人。', '他是神，与父同质，受生于未有世界以先；他又是人，与其母同质，生于这世界。', '他既是完全的神，又是具有人的灵魂和肉体的完全的人；', '以其神性，他与父同等，以其人性，他低于父。', '尽管既是神又是人，基督仍是一位，而非两位。', '他是一位，并非因他的神性变为人性，乃是在神性中取了人性；', '他是一位，并非因两质相混，乃是因神人二性合于一个位格。', '正如人是灵与肉的合一体一样，基督是神与人的合一体。', '基督为救我们而受难，降在阴间，又从死里复活，', '升天，坐在父的右边，将来必从那里降临，审判活人死人；', '他降临时，所有死人都必身体复活，供认所行的一切事；', '行善者必得永生，作恶者必入永火。', '这是大公信仰。人若非坚定不移地相信，就不能得救。阿们！']

assert len(APOSTLES_ZH)==12 and len(NICENE_ZH)==12 and len(ATH_ZH)==42
